/* ============================================================
   PATCH 1.0.35 — единый перехватчик /api/tracker/log/save
   Порядок: собрать multi-поля → overflow → 409 → отправить →
   auto-assign → close modals.
   ============================================================ */
(function(){
'use strict';
if (window.__trkLogSaveUnifiedV1035) return;
window.__trkLogSaveUnifiedV1035 = true;

var _native = window.fetch;
if (typeof _native !== 'function') return;

function _csrf(){ try { return window.REESTR_CSRF || ''; } catch(e){ return ''; } }
function _notify(msg, kind){
    if (typeof window.__trackerNotify === 'function') {
        try { window.__trackerNotify(msg, kind); return; } catch(e){}
    }
}
function _collectExtra(){
    var box = document.getElementById('logExtraDataList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row input[type="text"]').forEach(function(inp){
        var v = (inp.value || '').trim();
        if (v) out.push(v);
    });
    return out;
}
function _collectOrders(){
    var box = document.getElementById('logOrdersList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row').forEach(function(row){
        var d = row.querySelector('.task-order-desc');
        var v = row.querySelector('.task-order-val');
        var vv = v ? (v.value || '').trim() : '';
        if (vv) out.push({ description: d ? (d.value || '').trim() : '', value: vv });
    });
    return out;
}
function _collectLinks(){
    var box = document.getElementById('logLinksList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row').forEach(function(row){
        var d = row.querySelector('.task-link-desc');
        var u = row.querySelector('.task-link-url');
        var uu = u ? (u.value || '').trim() : '';
        if (uu) out.push({ description: d ? (d.value || '').trim() : '', url: uu });
    });
    return out;
}

function _enrichBody(body){
    // 1. Multi-поля из DOM (всегда)
    var extra = _collectExtra();
    var orders = _collectOrders();
    var links = _collectLinks();
    if (extra.length) body.extra_data = extra;
    if (orders.length) body.orders = orders;
    if (links.length) body.links = links;
    // 2. Описание из textarea
    var ta = document.getElementById('log_comment');
    if (ta) {
        if (!body.comment) body.comment = (ta.value || '').trim();
        if (!body.description) body.description = (ta.value || '').trim();
    }
    // 3. Merge в задачу всегда
    body.merge_into_task = 1;
    return body;
}

function _onSuccess(body, d){
    // Auto-assign сотрудника в задачу
    try {
        if (body.employee_id && body.task_id) {
            var st = window.__trkState || {};
            var task = (st.tasks || []).find(function(t){ return t.id === body.task_id; });
            if (task) {
                var cur = Array.isArray(task.assignees) ? task.assignees.slice() : [];
                if (cur.indexOf(body.employee_id) === -1) {
                    cur.push(body.employee_id);
                    var payload = {
                        id: task.id, name: task.name || '', icon: task.icon || '📋',
                        description: task.description || '', status: task.status || 'active',
                        start_date: task.start_date || '', deadline: task.deadline || '',
                        completed_at: task.completed_at || '', folder: task.folder || '',
                        order_ref: task.order_ref || '', tags: (task.tags || []).slice(),
                        assignees: cur, department_ids: (task.department_ids || []).slice(),
                        is_urgent: !!task.is_urgent,
                        links: (task.links || []).slice(), orders: (task.orders || []).slice()
                    };
                    var hdrs = {'Content-Type': 'application/json'};
                    if (_csrf()) hdrs['X-CSRF-Token'] = _csrf();
                    _native('/api/tracker/task/save', {
                        method: 'POST', headers: hdrs, credentials: 'same-origin',
                        body: JSON.stringify(payload)
                    }).catch(function(){});
                    task.assignees = cur;
                }
            }
        }
    } catch (e) { console.error('[unified-log-save] auto-assign', e); }
    // Close all modals
    ['logModal', 'dayModal', 'taskModal'].forEach(function(id){
        var m = document.getElementById(id);
        if (m && m.classList.contains('active')) m.classList.remove('active');
    });
    // Refresh
    var _refresh = (typeof window.__trkRefreshAll === 'function')
        ? window.__trkRefreshAll
        : (typeof window.__trkRenderCalendar === 'function' ? window.__trkRenderCalendar : null);
    if (_refresh) { setTimeout(function(){ Promise.resolve(_refresh()); }, 80); }
}

window.fetch = function(url, opts){
    var isLogSave = (typeof url === 'string' && url.indexOf('/api/tracker/log/save') !== -1);
    var isPost = opts && (opts.method || 'GET').toUpperCase() === 'POST';
    if (!isLogSave || !isPost) {
        return _native.apply(this, arguments);
    }

    var body = {};
    try { body = JSON.parse(opts.body || '{}'); } catch (e) {}
    body = _enrichBody(body);

    var self = this;
    var newOpts = Object.assign({}, opts, { body: JSON.stringify(body) });

    return _native.call(self, url, newOpts).then(function(r){
        // 409 already_logged_today
        if (r.status === 409) {
            return r.clone().json().then(function(d){
                if (d && d.error === 'already_logged_today') {
                    var msg = 'У сотрудника «' + (d.employee_name || '') + '» уже есть отметка '
                            + (d.date || '') + ' по задаче «' + (d.task_name || '') + '».\n\nОткрыть её?';
                    if (window.confirm(msg)) {
                        var st = window.__trkState || {};
                        var entry = null;
                        if (st.calendar && st.calendar.days) {
                            for (var i = 0; i < st.calendar.days.length; i++) {
                                var day = st.calendar.days[i];
                                var arr = day.entries || [];
                                for (var j = 0; j < arr.length; j++) {
                                    if (String(arr[j].id) === String(d.existing_id)) { entry = arr[j]; break; }
                                }
                                if (entry) break;
                            }
                        }
                        if (entry && typeof window.__trkOpenLogModal === 'function') {
                            setTimeout(function(){ window.__trkOpenLogModal(entry); }, 80);
                        }
                    }
                    return new Response(JSON.stringify({success: false, error: 'cancelled'}), {
                        status: 200, headers: {'Content-Type': 'application/json'}
                    });
                }
                return r;
            });
        }
        if (!r || !r.ok) return r;
        return r.clone().json().then(function(d){
            if (d && d.success && !d.cancelled) {
                _onSuccess(body, d);
            }
            return r;
        }).catch(function(){ return r; });
    });
};

window.__trkLogSaveUnified = true;
})();

